/**
 * UTS-46 mapping and Unicode script lookup over the pinned range tables in
 * lib/domain/data/. Both tables are generated by scripts/domain-tools/refresh-datasets.mjs
 * from one Unicode version, so the converter and the domain engine can never
 * disagree about what a character is.
 */

import idnaData from "./data/idna-mapping.json" with { type: "json" };
import nameData from "./data/unicode-names.json" with { type: "json" };
import scriptData from "./data/unicode-scripts.json" with { type: "json" };

type Range = [number, number, string];

const idnaRanges = idnaData.ranges as Range[];
const scriptRanges = scriptData.ranges as Range[];
const characterNames = nameData.names as Record<string, string>;

export const UNICODE_VERSION = idnaData.unicodeVersion as string;

if (nameData.unicodeVersion !== UNICODE_VERSION || scriptData.unicodeVersion !== UNICODE_VERSION) {
  throw new Error("Unicode mapping, script, and character-name data must use the same version.");
}

function lookup(ranges: Range[], codePoint: number): string | null {
  let low = 0;
  let high = ranges.length - 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    const [start, end, value] = ranges[mid];
    if (codePoint < start) high = mid - 1;
    else if (codePoint > end) low = mid + 1;
    else return value;
  }
  return null;
}

export type IdnaStatus =
  | "valid"
  | "ignored"
  | "disallowed"
  | "deviation"
  | "mapped"
  | "disallowed_STD3_valid"
  | "disallowed_STD3_mapped";

export type IdnaEntry = { status: IdnaStatus; mapping: string | null };

export function idnaStatus(codePoint: number): IdnaEntry {
  const raw = lookup(idnaRanges, codePoint);
  if (raw === null) return { status: "disallowed", mapping: null };
  const [status, mapping] = raw.split(":");
  if (!mapping) return { status: status as IdnaStatus, mapping: null };
  const replacement = mapping
    .split(",")
    .filter(Boolean)
    .map((hex) => String.fromCodePoint(parseInt(hex, 16)))
    .join("");
  return { status: status as IdnaStatus, mapping: replacement };
}

export function scriptOf(codePoint: number): string {
  return lookup(scriptRanges, codePoint) ?? "Unknown";
}

/** ASCII letters, digits and hyphen. The LDH rule STD3 restricts hostnames to. */
function isLdhAscii(codePoint: number) {
  return (
    (codePoint >= 0x61 && codePoint <= 0x7a) ||
    (codePoint >= 0x41 && codePoint <= 0x5a) ||
    (codePoint >= 0x30 && codePoint <= 0x39) ||
    codePoint === 0x2d
  );
}

/**
 * Apply UTS-46 mapping to one label.
 *
 * Non-transitional processing: deviation characters (ß, ς, ZWJ, ZWNJ) are kept
 * rather than mapped, which is what browsers and registries do today.
 *
 * UseSTD3ASCIIRules is a parameter of UTS-46 rather than a column in the mapping
 * table. The table marks characters like underscore and tilde as `valid` with an
 * NV8 note, so restricting ASCII to letters, digits and hyphen has to be done
 * here. Without this the function would accept `bad_name` as a registrable label.
 */
export function mapLabel(
  label: string,
  options: { useStd3AsciiRules?: boolean } = {},
): { output: string; disallowed: boolean; disallowedCharacters: string[] } {
  const useStd3 = options.useStd3AsciiRules !== false;
  let output = "";
  const disallowedCharacters: string[] = [];
  for (const character of label) {
    const codePoint = character.codePointAt(0) as number;
    const { status, mapping } = idnaStatus(codePoint);
    if (status === "mapped" || status === "disallowed_STD3_mapped") {
      output += mapping ?? character;
      continue;
    }
    if (status === "ignored") continue;
    if (status === "disallowed" || status === "disallowed_STD3_valid") {
      disallowedCharacters.push(character);
      output += character;
      continue;
    }
    if (useStd3 && codePoint < 0x80 && !isLdhAscii(codePoint)) {
      disallowedCharacters.push(character);
    }
    output += character;
  }
  return { output, disallowed: disallowedCharacters.length > 0, disallowedCharacters };
}

export type CharacterDetail = {
  character: string;
  codePoint: string;
  name: string;
  script: string;
};

const HANGUL_LEADS = ["G", "GG", "N", "D", "DD", "R", "M", "B", "BB", "S", "SS", "", "J", "JJ", "C", "K", "T", "P", "H"];
const HANGUL_VOWELS = ["A", "AE", "YA", "YAE", "EO", "E", "YEO", "YE", "O", "WA", "WAE", "OE", "YO", "U", "WEO", "WE", "WI", "YU", "EU", "YI", "I"];
const HANGUL_TAILS = ["", "G", "GG", "GS", "N", "NJ", "NH", "D", "L", "LG", "LM", "LB", "LS", "LT", "LP", "LH", "M", "B", "BS", "S", "SS", "NG", "J", "C", "K", "T", "P", "H"];

function algorithmicName(codePoint: number) {
  if (codePoint >= 0xac00 && codePoint <= 0xd7a3) {
    const offset = codePoint - 0xac00;
    const lead = Math.floor(offset / 588);
    const vowel = Math.floor((offset % 588) / 28);
    const tail = offset % 28;
    return `HANGUL SYLLABLE ${HANGUL_LEADS[lead]}${HANGUL_VOWELS[vowel]}${HANGUL_TAILS[tail]}`;
  }
  if ((codePoint >= 0x3400 && codePoint <= 0x4dbf)
    || (codePoint >= 0x4e00 && codePoint <= 0x9fff)
    || (codePoint >= 0x20000 && codePoint <= 0x2fa1f)
    || (codePoint >= 0x30000 && codePoint <= 0x323af)) {
    return `CJK UNIFIED IDEOGRAPH-${codePoint.toString(16).toUpperCase()}`;
  }
  return null;
}

export function describeCharacters(value: string): CharacterDetail[] {
  return Array.from(value, (character) => {
    const codePoint = character.codePointAt(0) as number;
    const script = scriptOf(codePoint);
    return {
      character,
      codePoint: `U+${codePoint.toString(16).toUpperCase().padStart(4, "0")}`,
      name: characterNames[codePoint.toString(16).toUpperCase()] ?? algorithmicName(codePoint) ?? "UNASSIGNED OR UNNAMED CHARACTER",
      script,
    };
  });
}

/**
 * Scripts that carry no identity of their own. Digits, hyphens and combining
 * marks appear in names of every script, so counting them would report almost
 * every name as mixed.
 */
const NEUTRAL_SCRIPTS = new Set(["Common", "Inherited", "Unknown"]);

export type ScriptAnalysis = {
  scripts: string[];
  mixed: boolean;
  /** Latin mixed with another script is the shape used for spoofing. */
  latinMixedWithOther: boolean;
};

export function analyzeScripts(label: string): ScriptAnalysis {
  const scripts = new Set<string>();
  for (const character of label) {
    const script = scriptOf(character.codePointAt(0) as number);
    if (!NEUTRAL_SCRIPTS.has(script)) scripts.add(script);
  }
  const list = [...scripts].sort();
  return {
    scripts: list,
    mixed: list.length > 1,
    latinMixedWithOther: list.length > 1 && list.includes("Latin"),
  };
}
